window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[208]={"id":"208","numero":208,"titre":"Insuffisance respiratoire chronique","objectifs":[{"id":"208-1","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la définition d’une insuffisance respiratoire chronique (IRC)","contenu":"<p>L'<span class=\"kw-def\">insuffisance respiratoire chronique (IRC)</span> est l'<strong>incapacité de l'appareil respiratoire à assurer <span class=\"kw-clinique\">les</span> échanges gazeux</strong> — <span class=\"kw-clinique\">oxygénation du sang</span> et <span class=\"kw-clinique\">élimination du CO₂</span>. C'est un processus <strong><span class=\"kw-alerte\">irréversible</span></strong> (<span class=\"kw-def\">pronostic</span> sévère), <span class=\"kw-def\">lentement évolutif</span> dans la majorité des cas.</p>\n      <p><strong>Définition gazométrique</strong> — <span class=\"kw-def\">hypoxémie</span> avec <span class=\"kw-bio\">PaO₂</span> <span class=\"kw-chiffre\">&lt; 70 mmHg</span>, mesurée en <span class=\"kw-chiffre\">air ambiant</span>, au <span class=\"kw-chiffre\">repos</span>, à l'<span class=\"kw-chiffre\">état stable</span>, à <span class=\"kw-chiffre\">2 reprises</span> à <span class=\"kw-chiffre\">≥ 2 semaines</span> d'intervalle.</p>\n      <table >\n        <thead><tr><th>Forme</th><th><span class=\"kw-bio\">Gazométrie</span></th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-def\">IRC hypoxémique</span></th><td><span class=\"kw-bio\">PaO₂</span> ↓ et <span class=\"kw-bio\">PaCO₂</span> normale ou diminuée</td></tr>\n          <tr><th><span class=\"kw-def\">IRC hypercapnique</span></th><td><span class=\"kw-bio\">PaO₂</span> ↓ et <strong><span class=\"kw-bio\">PaCO₂</span> ↑</strong></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>IRC grave.</strong> définie par <span class=\"kw-bio\">PaO₂</span> <strong><span class=\"kw-alerte\">&lt; 60 mmHg</span></strong> → concerne <span class=\"kw-chiffre\">300 000 patients</span> en France ; reconnue par la <strong>HAS</strong> comme <span class=\"kw-def\">critère de</span> prescription d'<span class=\"kw-ttt\">oxygénothérapie de longue durée</span> ; ouvre droit à l'exonération du ticket modérateur au titre de l'<strong><span class=\"kw-def\">ALD 14</span></strong>.</div>\n      <p><strong>3 étiologies <span class=\"kw-clinique\">les</span> plus fréquentes</strong> : <span class=\"kw-etio\">BPCO</span> · <span class=\"kw-etio\">syndrome obésité-hypoventilation</span> · <span class=\"kw-etio\">maladies neuromusculaires</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 203 — <span class=\"kw-clinique\">Dyspnée</span> · 359 — <span class=\"kw-alerte\">Détresse</span> et <span class=\"kw-ci\">insuffisance respiratoire</span> aiguë</em></p>","frequence":2},{"id":"208-2","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les données cliniques permettant d’orienter vers une IRC obstructive et vers une IRC restrictive","contenu":"<p><strong>Symptômes</strong> — la <span class=\"kw-clinique\">dyspnée d'effort</span> (ou l'aggravation d'une <span class=\"kw-clinique\">dyspnée</span> préexistante) est <strong>quasi-constante</strong> dans l'IRC : initialement à l'effort, puis pour des efforts modestes, voire au repos.</p>\n      <ul>\n        <li><strong>Altération du sommeil</strong> (fréquente) : <span class=\"kw-clinique\">sommeil non réparateur</span>, <span class=\"kw-clinique\">réveils nocturnes</span>, <span class=\"kw-clinique\">céphalées frontales matinales</span>, <span class=\"kw-clinique\">somnolence diurne excessive</span>, <span class=\"kw-clinique\">troubles de la mémoire et de la concentration</span>, <span class=\"kw-clinique\">syndrome anxio-dépressif</span>.</li>\n        <li><strong>Signes d'hypercapnie</strong> : <span class=\"kw-clinique\">astérixis</span> (<span class=\"kw-clinique\">flapping</span> tremor), <span class=\"kw-clinique\">céphalées</span>, <span class=\"kw-clinique\">hypervascularisation des conjonctives</span>, <span class=\"kw-clinique\">sueurs</span>, <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-clinique\">HTA</span>, troubles de la vigilance jusqu'au <span class=\"kw-alerte\">coma hypercapnique</span>.</li>\n      </ul>\n      <p><strong>Symptômes selon la pathologie initiale</strong> — orientent vers le mécanisme :</p>\n      <table >\n        <thead><tr><th>Pathologie</th><th>Symptôme évocateur</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-etio\">BPCO</span></th><td><span class=\"kw-clinique\">dyspnée d'effort</span>, <span class=\"kw-clinique\">toux</span> ± <span class=\"kw-clinique\">expectorations</span></td></tr>\n          <tr><th><span class=\"kw-etio\">Fibrose pulmonaire</span></th><td><span class=\"kw-clinique\">toux sèche</span></td></tr>\n          <tr><th><span class=\"kw-etio\">Syndrome obésité-hypoventilation</span></th><td>altération de la <span class=\"kw-clinique\">qualité du sommeil</span></td></tr>\n          <tr><th><span class=\"kw-etio\">Maladie neuromusculaire</span></th><td><span class=\"kw-clinique\">encombrements bronchiques itératifs</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Signes cliniques</strong> — en rapport avec la pathologie initiale, plus :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Cyanose</span> : <span class=\"kw-alerte\">signe de gravité</span> inconstant, traduit la présence de <span class=\"kw-alerte\">&gt; 5 g/dL d'hémoglobine désoxygénée</span>.</li>\n        <li>Signes d'<span class=\"kw-clinique\">insuffisance cardiaque droite</span> à un <span class=\"kw-def\">stade</span> évolué : <span class=\"kw-clinique\">turgescence jugulaire</span>, <span class=\"kw-clinique\">reflux hépato-jugulaire</span>, <span class=\"kw-clinique\">œdèmes des membres inférieurs</span>.</li>\n        <li>Signes d'hypercapnie : <span class=\"kw-clinique\">astérixis</span>, <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-clinique\">HTA</span>.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 209 — BPCO · 210 — Pneumopathie interstitielle diffuse · 253 — <span class=\"kw-etio\">Obésité</span> · 98 — Myasthénie</em></p>","frequence":4},{"id":"208-3","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’hypertension pulmonaire (HTP) de l’adulte","contenu":"<p>L'<span class=\"kw-def\">hypertension pulmonaire (HTP)</span> de l'adulte se définit par <strong>2 critères</strong> mesurés au <span class=\"kw-bio\">cathétérisme cardiaque droit</span> :</p>\n      <ul>\n        <li><span class=\"kw-def\">Pression artérielle pulmonaire moyenne (PAPm)</span> <strong><span class=\"kw-chiffre\">&gt; 20 mmHg</span></strong> ;</li>\n        <li><span class=\"kw-def\">Résistances vasculaires pulmonaires</span> <strong><span class=\"kw-chiffre\">&gt; 3 unités Wood</span></strong>.</li>\n      </ul>\n      <p>Lorsqu'elle est <strong>secondaire à une IRC</strong>, l'<span class=\"kw-clinique\">HTP</span> est classée dans le <strong><span class=\"kw-def\">groupe 3</span></strong>. Elle est <span class=\"kw-etio\">secondaire à la vasoconstriction pulmonaire hypoxique</span>, à l'origine d'un <span class=\"kw-def\">remodelage vasculaire</span> à long terme.</p>\n      <div class=\"callout callout-info\"><strong>Démarche diagnostique.</strong> <span class=\"kw-clinique\">HTP</span> <em>suspectée</em> par une <span class=\"kw-imagerie\">PAPS &gt; 35 mmHg</span> évaluée à l'<span class=\"kw-imagerie\">échographie cardiaque</span> ; <em>confirmée</em> par le <span class=\"kw-bio\">cathétérisme cardiaque droit</span> (rarement indiqué en cas d'IRC déjà documentée).</div>","frequence":0},{"id":"208-4","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les symptômes qui peuvent faire évoquer le diagnostic d’HTP","contenu":"<p>Au cours de l'IRC, l'<span class=\"kw-clinique\">HTP</span> est responsable d'une <strong><span class=\"kw-alerte\">aggravation des symptômes et du pronostic</span></strong>. <span class=\"kw-clinique\">Les</span> manifestations sont peu spécifiques et dominées par la <span class=\"kw-clinique\">dyspnée</span> et les signes de <span class=\"kw-clinique\">cœur pulmonaire chronique</span> :</p>\n      <ul>\n        <li>Aggravation de la <span class=\"kw-clinique\">dyspnée d'effort</span> ;</li>\n        <li>Signes de <span class=\"kw-clinique\">dysfonction ventriculaire droite</span>, notamment lors des épisodes d'<span class=\"kw-alerte\">insuffisance respiratoire aiguë</span> ;</li>\n        <li>Signes d'<span class=\"kw-clinique\">insuffisance cardiaque droite</span> : <span class=\"kw-clinique\">turgescence jugulaire</span>, <span class=\"kw-clinique\">reflux hépato-jugulaire</span>, <span class=\"kw-clinique\">œdèmes des membres inférieurs</span>.</li>\n      </ul>","frequence":0},{"id":"208-5","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les explorations fonctionnelles permettant d’orienter vers une IRC obstructive et vers une IRC restrictive","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-bio\">explorations fonctionnelles respiratoires (EFR)</span> orientent le mécanisme de l'IRC selon le trouble ventilatoire identifié. <strong>Objectif le plus tombé de l'item.</strong></p>\n      <table >\n        <thead><tr><th>Profil EFR</th><th>Mécanisme &amp; étiologies</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-def\">IRC obstructive</span><br><em>(trouble ventilatoire obstructif, TVO)</em></th><td><strong>Mécanisme :</strong> inadéquation <span class=\"kw-def\">ventilation/perfusion</span> (corrigée efficacement par l'<span class=\"kw-ttt\">oxygénothérapie de longue durée</span>)<br><strong>Étiologies :</strong> <span class=\"kw-etio\">BPCO</span> (cause principale) ; <span class=\"kw-etio\">asthme fixé vieilli</span> ; <span class=\"kw-etio\">bronchiolite</span></td></tr>\n          <tr><th><span class=\"kw-def\">IRC restrictive</span><br><em>(trouble ventilatoire restrictif, TVR)</em></th><td><strong>Avec anomalie de diffusion :</strong> <span class=\"kw-etio\">pneumopathies interstitielles</span> (fibrose ++) — atteinte de la <span class=\"kw-def\">diffusion alvéolo-capillaire</span><br><strong>Sans anomalie de diffusion :</strong> <span class=\"kw-etio\">maladies neuromusculaires</span> ; <span class=\"kw-etio\">syndrome obésité-hypoventilation</span> ; <span class=\"kw-etio\">atteinte de la paroi thoracique</span> (cyphoscoliose) ; <span class=\"kw-etio\">atteintes pleurales</span> (pachypleurite)</td></tr>\n          <tr><th><span class=\"kw-def\">IRC mixte</span><br><em>(TVO + TVR)</em></th><td><span class=\"kw-etio\">Mucoviscidose</span> ; <span class=\"kw-etio\">dilatation des bronches</span> (bronchectasies) ; <span class=\"kw-etio\">séquelles de tuberculose</span> ; <span class=\"kw-etio\">silicose</span> et autres pneumoconioses</td></tr>\n          <tr><th><span class=\"kw-def\">HTAP</span><br><em>(volumes normaux)</em></th><td>IRC <strong>sans anomalie des volumes pulmonaires</strong>, avec <strong>seulement une anomalie de la diffusion</strong> → orientation vers une <span class=\"kw-etio\">HTAP</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Repère.</strong> La <span class=\"kw-def\">pachypleurite</span> = épaississement et rigidité de la plèvre gênant l'expansion pulmonaire ; étiologies = séquelles étendues d'<span class=\"kw-etio\">hémothorax</span> ou de <span class=\"kw-etio\">pleurésies infectieuses</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 209 — BPCO · 210 — Pneumopathie interstitielle diffuse · 188 — Asthme - Rhinite</em></p>","frequence":6},{"id":"208-6","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les modalités d’interprétation des explorations fonctionnelles permettant d’orienter vers une IRC obstructive et vers une IRC restrictive","contenu":"<p>Le <strong><span class=\"kw-def\">diagnostic positif</span></strong> repose sur <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">gaz du sang</span> : <span class=\"kw-bio\">PaO₂</span> <span class=\"kw-chiffre\">&lt; 70 mmHg</span> (<span class=\"kw-def\">air</span> ambiant, repos, état stable, 2 reprises à <span class=\"kw-chiffre\">≥ 2 semaines</span>). Une <span class=\"kw-bio\">acidose respiratoire compensée par les bicarbonates</span> suggère une <strong><span class=\"kw-def\">hypercapnie chronique</span></strong> (<span class=\"kw-bio\">vs</span> aiguë).</p>\n      <p><strong>Syndrome <span class=\"kw-etio\">obésité</span>-hypoventilation</strong> — association :</p>\n      <ul>\n        <li><span class=\"kw-bio\">Hypercapnie diurne</span> (<span class=\"kw-bio\">PaCO₂</span> <span class=\"kw-chiffre\">≥ 45 mmHg</span>) ;</li>\n        <li><span class=\"kw-bio\">IMC</span> <span class=\"kw-chiffre\">≥ 30</span> ;</li>\n        <li>en l'<strong>absence d'autre cause</strong> d'hypercapnie.</li>\n      </ul>\n      <p><strong>Atteinte pariétale (cyphoscoliose idiopathique)</strong> — la déformation augmente la charge imposée à la pompe, entraînant une IRC vers <span class=\"kw-chiffre\">40-50 ans</span>. <span class=\"kw-def\">Facteurs de risque</span> d'IRC :</p>\n      <ul>\n        <li>Âge de survenue de la déformation <span class=\"kw-chiffre\">&lt; 5 ans</span> ;</li>\n        <li><span class=\"kw-def\">Longueur</span> de la déformation ;</li>\n        <li>Siège <strong>haut situé</strong> ;</li>\n        <li>Importance de l'<span class=\"kw-def\">angulation</span>.</li>\n      </ul>\n      <p>Dans la <span class=\"kw-etio\">pneumopathie interstitielle</span>, l'atteinte de la <span class=\"kw-def\">diffusion alvéolo-capillaire</span> est l'anomalie principale (<span class=\"kw-clinique\">hypoxémie à l'effort</span> d'abord, puis nocturne et diurne) ; l'<span class=\"kw-clinique\">hypoventilation</span> y est rare et témoigne d'une atteinte sévère ou d'une fonte musculaire associée.</p>","frequence":0},{"id":"208-7","rang":"A","rubrique":"Identifier une urgence","titre":"Identifier une décompensation d’IRC et en apprécier la gravité","contenu":"<p>La <span class=\"kw-alerte\">décompensation</span> en <strong><span class=\"kw-alerte\">insuffisance respiratoire aiguë (IRA)</span></strong> est le <strong>principal risque évolutif</strong> de l'IRC.</p>\n      <p><strong>Principales causes d'exacerbation</strong> : <span class=\"kw-etio\">infections respiratoires basses</span> (bronchites, pneumonies) ; <span class=\"kw-etio\">OAP</span> ; <span class=\"kw-etio\">troubles du rythme</span> ; <span class=\"kw-etio\">embolie pulmonaire</span>.</p>\n      <p><strong>Autres facteurs déclenchants</strong> :</p>\n      <ul>\n        <li><strong>Médicaments :</strong> <span class=\"kw-ci\">benzodiazépines</span>, <span class=\"kw-ci\">opiacés</span> ;</li>\n        <li><span class=\"kw-etio\">Chirurgie</span> abdominale sus-mésocolique ou thoracique ; <span class=\"kw-etio\">traumatisme thoracique</span> ; <span class=\"kw-etio\">fracture-tassement vertébral</span> ; <span class=\"kw-etio\">pneumothorax</span> ;</li>\n        <li><strong>Aucune cause retrouvée dans <span class=\"kw-chiffre\">⅓ des cas</span></strong>.</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Signes de gravité</span>.</strong> signes de <span class=\"kw-alerte\">lutte</span> ; signes de <span class=\"kw-alerte\">défaillance</span> ; <span class=\"kw-bio\">pH</span> <span class=\"kw-alerte\">&lt; 7,35</span> ; <span class=\"kw-bio\">PaO₂</span> <span class=\"kw-alerte\">&lt; 60 mmHg</span> ; <span class=\"kw-bio\">PaCO₂</span> <span class=\"kw-alerte\">&gt; 45 mmHg</span> ; élévation des <span class=\"kw-bio\">lactates</span>.</div>\n      <p><strong>Prise en charge</strong> — <span class=\"kw-ttt\">oxygénothérapie</span> (traitement clé) ± <span class=\"kw-ttt\">ventilation mécanique</span> si <span class=\"kw-alerte\">acidose respiratoire décompensée</span> dans le cadre d'une IRA hypercapnique.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 359 — <span class=\"kw-alerte\">Détresse</span> et <span class=\"kw-ci\">insuffisance respiratoire</span> aiguë · 226 — Thrombose veineuse profonde - EP</em></p>","frequence":1},{"id":"208-8","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les conséquences de l’IRC : insuffisance respiratoire aigüe, polyglobulie, hypertension pulmonaire, rétention hydrosodée","contenu":"<table >\n        <thead><tr><th>Conséquence</th><th>Mécanisme &amp; présentation</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-def\">Polyglobulie</span></th><td>Production d'<span class=\"kw-bio\">EPO</span> en réponse à l'<span class=\"kw-def\">hypoxémie chronique</span> (phénomène adaptatif, inconstant) → ↑ <span class=\"kw-clinique\">viscosité sanguine</span> → <span class=\"kw-alerte\">risque accru de thromboses</span> artérielles et veineuses</td></tr>\n          <tr><th><span class=\"kw-def\">Rétention hydro-sodée</span></th><td><strong>Causes :</strong> anomalie de régulation du facteur natriurétique, ou conséquence de l'HTAP secondaire<br><strong>Présentation :</strong> <span class=\"kw-clinique\">œdèmes déclives</span> fréquents</td></tr>\n          <tr><th><span class=\"kw-def\">Hypertension pulmonaire</span></th><td>Secondaire à la <span class=\"kw-def\">vasoconstriction pulmonaire hypoxique</span> → remodelage vasculaire → <span class=\"kw-alerte\">cœur pulmonaire chronique</span> (↑ résistances vasculaires pulmonaires + ↑ viscosité + rétention hydro-sodée) → <span class=\"kw-clinique\">dysfonction ventriculaire droite</span>. Signification <strong>péjorative</strong> sur le <span class=\"kw-def\">pronostic</span></td></tr>\n          <tr><th><span class=\"kw-def\">Insuffisance respiratoire aiguë</span></th><td><span class=\"kw-alerte\">Décompensation</span> = principal risque évolutif (cf. objectif « Identifier une <span class=\"kw-alerte\">décompensation</span> d'IRC »)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Signes d'hypercapnie</strong> à reconnaître :</p>\n      <ul>\n        <li><strong>Vigilance :</strong> <span class=\"kw-clinique\">agitation</span>, <span class=\"kw-clinique\">confusion</span>, <span class=\"kw-clinique\">ralentissement idéo-moteur</span>, jusqu'au <span class=\"kw-alerte\">coma hypercapnique</span> ;</li>\n        <li><strong>Réponse adrénergique :</strong> <span class=\"kw-clinique\">tremblements</span>, <span class=\"kw-clinique\">sueurs</span>, <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-clinique\">HTA</span> ;</li>\n        <li><strong>Effet vasodilatateur du CO₂ :</strong> <span class=\"kw-clinique\">céphalées</span>, <span class=\"kw-clinique\">hypervascularisation conjonctivale</span> ; signe clé = <span class=\"kw-clinique\">astérixis</span> (<span class=\"kw-clinique\">flapping</span> tremor).</li>\n      </ul>","frequence":1},{"id":"208-9","rang":"B","rubrique":"Physiopathologie/étiologies","titre":"Différencier les IRC selon leur mécanisme physiopathologique (liées à l’échangeur vs pompe ventilatoire ou commande centrale vs vascularisation pulmonaire)","contenu":"<p>Trois grands mécanismes (souvent associés) peuvent être à l'origine d'une <span class=\"kw-def\">hypoxémie chronique</span> :</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Sous-types &amp; étiologies</th><th>Réponse à l'O₂</th></tr></thead>\n        <tbody>\n          <tr><th>Anomalies <span class=\"kw-def\">ventilation/perfusion</span><br><em>(échangeur pulmonaire)</em></th><td><strong>Effet shunt</strong> (alvéoles perfusées mais mal ventilées, V/Q &lt; 1) : <span class=\"kw-etio\">BPCO</span> ; <span class=\"kw-etio\">asthme aigu grave</span> ; <span class=\"kw-etio\">embolie pulmonaire</span><br><strong>Shunt vrai anatomique</strong> : <span class=\"kw-etio\">foramen ovale perméable</span> ; <span class=\"kw-etio\">malformation artério-veineuse pulmonaire</span> ; <span class=\"kw-etio\">cardiopathie cyanogène</span><br><strong>Shunt vrai fonctionnel</strong> (perfusées mais non ventilées) : <span class=\"kw-etio\">atélectasie</span> ; <span class=\"kw-etio\">OAP</span> ; <span class=\"kw-etio\">pneumonie</span> ; <span class=\"kw-etio\">SDRA</span> ; <span class=\"kw-etio\">hémorragie intra-alvéolaire</span></td><td><strong>Effet shunt :</strong> corrigé par faibles débits d'O₂ ✅<br><strong>Shunt vrai :</strong> <span class=\"kw-alerte\">non ou mal corrigé</span> même à haut débit ❌</td></tr>\n          <tr><th><span class=\"kw-def\">Hypoventilation alvéolaire</span><br><em>(pompe ventilatoire / commande)</em></th><td><strong>Hypoventilation pure</strong> : atteinte de la <span class=\"kw-etio\">commande centrale</span> ou de la <span class=\"kw-etio\">pompe respiratoire</span> (muscles, cage thoracique, voies nerveuses)<br><strong>Effet espace mort</strong> : <span class=\"kw-etio\">embolie pulmonaire</span> ; <span class=\"kw-etio\">emphysème</span> (destruction capillaire &gt; alvéolaire)</td><td>Hypoxémie <strong>corrigée</strong> par l'<span class=\"kw-ttt\">oxygénothérapie</span> ✅</td></tr>\n          <tr><th>Atteinte de la <span class=\"kw-def\">diffusion alvéolaire</span><br><em>(vascularisation pulmonaire)</em></th><td><strong>Membrane lésée :</strong> <span class=\"kw-etio\">PID</span><br><strong>Surface d'échange ↓ :</strong> versant alvéolaire (<span class=\"kw-etio\">emphysème</span>) ou vasculaire (<span class=\"kw-etio\">HTAP</span>)</td><td><span class=\"kw-clinique\">Hypoxémie à l'effort</span> (temps de <span class=\"kw-def\">contact</span> réduit) ; hypo/normocapnie</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 226 — Thrombose veineuse profonde - EP · 209 — BPCO · 210 — Pneumopathie interstitielle diffuse</em></p>","frequence":3},{"id":"208-10","rang":"B","rubrique":"Physiopathologie/étiologies","titre":"Connaître les principaux mécanismes responsables d’une hypoxémie et ceux responsables d’une hypercapnie","contenu":"<p><strong>Mécanismes d'hypoxémie</strong> : <span class=\"kw-def\">effet shunt</span> (mécanisme le plus fréquent), <span class=\"kw-def\">shunt vrai</span> (anatomique ou fonctionnel), <span class=\"kw-def\">hypoventilation alvéolaire</span>, <span class=\"kw-def\">effet espace mort</span> et <span class=\"kw-def\">trouble de la diffusion</span>.</p>\n      <div class=\"callout callout-info\"><strong>Repère gazométrique.</strong> dans l'<span class=\"kw-def\">effet shunt</span>, la différence alvéolo-artérielle est élevée : <span class=\"kw-bio\">PaO₂ + PaCO₂</span> <span class=\"kw-chiffre\">&lt; 120 mmHg</span>. Dans l'<span class=\"kw-def\">hypoventilation alvéolaire pure</span>, la différence est normale : <span class=\"kw-bio\">PaO₂ + PaCO₂</span> <span class=\"kw-chiffre\">&gt; 120 mmHg</span>.</div>\n      <p><strong>Mécanismes d'hypercapnie</strong> :</p>\n      <ul>\n        <li><span class=\"kw-def\">Hypoventilation alvéolaire</span> : la <span class=\"kw-bio\">capnie</span> est inversement proportionnelle à la ventilation alvéolaire (ventilation ÷ 2 → capnie × 2). Causes = atteinte de la <span class=\"kw-etio\">commande centrale</span> (ex. <span class=\"kw-ci\">opiacés</span>) ou de la <span class=\"kw-etio\">pompe ventilatoire</span> (fonction neuromusculaire, cage thoracique).</li>\n        <li><span class=\"kw-def\">Effet espace mort</span> (V/Q &gt; 1, zones ventilées non perfusées) : <span class=\"kw-etio\">embolie pulmonaire</span>, <span class=\"kw-etio\">emphysème</span>. C'est le <strong>principal mécanisme d'hypercapnie dans la BPCO</strong>.</li>\n      </ul>\n      <p>L'<span class=\"kw-def\">espace mort (Vd)</span> = part du volume courant (Vt) ne participant pas aux échanges = espace mort <span class=\"kw-def\">anatomique</span> (voies de conduction, ~<span class=\"kw-chiffre\">150 mL</span>) + espace mort <span class=\"kw-def\">alvéolaire</span> (négligeable chez le sujet sain, augmenté en cas d'<span class=\"kw-etio\">embolie pulmonaire</span> ou d'<span class=\"kw-etio\">emphysème</span>).</p>","frequence":0},{"id":"208-11","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications et les modalités de l’oxygénothérapie de longue durée","contenu":"<p><strong>Objectifs de l'<span class=\"kw-ttt\">oxygénothérapie de longue durée (OLD)</span></strong> : corriger l'<span class=\"kw-def\">hypoxémie chronique</span>, prévenir <span class=\"kw-clinique\">les</span> complications (<span class=\"kw-alerte\">HTAP</span>), et <strong>diminuer la <span class=\"kw-def\">mortalité</span></strong> des patients <span class=\"kw-etio\">BPCO</span> avec IRC.</p>\n      <p><strong>Conditions de remboursement</strong> — <span class=\"kw-bio\">PaO₂</span> mesurée à <span class=\"kw-chiffre\">2 reprises</span>, au repos, à l'état stable, à <span class=\"kw-chiffre\">≥ 2 semaines</span> d'intervalle :</p>\n      <table >\n        <thead><tr><th>Profil</th><th>Seuil de remboursement</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-def\">IRC restrictive</span></th><td><span class=\"kw-bio\">PaO₂</span> <strong><span class=\"kw-chiffre\">&lt; 60 mmHg</span></strong></td></tr>\n          <tr><th><span class=\"kw-def\">IRC obstructive</span></th><td><span class=\"kw-bio\">PaO₂</span> <strong><span class=\"kw-chiffre\">&lt; 55 mmHg</span></strong> ;<br><em>ou</em> <span class=\"kw-bio\">PaO₂</span> entre <span class=\"kw-chiffre\">55-60 mmHg</span> <strong>avec un signe d'hypoxie tissulaire :</strong><br>• <span class=\"kw-clinique\">polyglobulie</span> (<span class=\"kw-bio\">hématocrite</span> <span class=\"kw-chiffre\">&gt; 55 %</span>) ;<br>• <span class=\"kw-clinique\">insuffisance ventriculaire droite</span> / <span class=\"kw-alerte\">HTAP</span> ;<br>• <span class=\"kw-clinique\">désaturations nocturnes</span> non apnéiques (<span class=\"kw-bio\">SpO₂</span> moyenne <span class=\"kw-chiffre\">≤ 88 %</span>) ;<br>• <span class=\"kw-clinique\">OMI chronique</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-ci\">Contre-indication</span> / pièges.</strong> traitement remis en cause si poursuite du <span class=\"kw-ci\">tabagisme actif</span> (<span class=\"kw-alerte\">risque de brûlures graves du visage, voire d'incendie</span>). En revanche, l'<strong>hypercapnie n'est PAS une <span class=\"kw-ci\">contre-indication</span></strong> ❌ à l'OLD, à condition qu'elle soit corrigée par une <span class=\"kw-ttt\">ventilation à domicile</span>.</div>\n      <p><strong>Modalités d'administration</strong> : à <strong>domicile</strong>, par <span class=\"kw-ttt\">lunettes nasales</span> ; idéalement <span class=\"kw-chiffre\">24h/24</span>, au minimum <strong><span class=\"kw-chiffre\">≥ 15h/jour</span></strong> en couvrant la <strong>nuit</strong> et l'<strong>activité physique</strong>. Objectif = débit permettant une <span class=\"kw-bio\">PaO₂</span> <span class=\"kw-chiffre\">&gt; 60 mmHg</span> ou une <span class=\"kw-bio\">SpO₂</span> <span class=\"kw-chiffre\">&gt; 90 %</span> au repos et à l'effort. Sources : <span class=\"kw-ttt\">oxygène gazeux</span> (concentrateur) ou <span class=\"kw-ttt\">oxygène liquide</span> (réservoir <span class=\"kw-chiffre\">30-40 L</span> à −<span class=\"kw-chiffre\">183 °C</span>), d'efficacité équivalente.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 75 — Addiction Tabac · 209 — BPCO</em></p>","frequence":3},{"id":"208-12","rang":"B","rubrique":"Prise en charge","titre":"Connaître les implications médico-sociales de l’IRC (Affection de Longue Durée)","contenu":"<ul>\n        <li>L'<span class=\"kw-alerte\">IRC grave</span> (<span class=\"kw-bio\">PaO₂</span> <span class=\"kw-chiffre\">&lt; 60 mmHg</span>, en <span class=\"kw-def\">air</span> ambiant, au repos, à l'état stable) est reconnue par la <strong>HAS</strong> comme une <span class=\"kw-def\">affection de longue durée</span>.</li>\n        <li>Elle relève de l'<strong><span class=\"kw-def\">ALD 14</span></strong> (« <span class=\"kw-ci\">insuffisance respiratoire</span> chronique grave »), concernant près de <span class=\"kw-chiffre\">300 000 patients</span> en France.</li>\n        <li>Elle ouvre droit à l'<span class=\"kw-def\">exonération du ticket modérateur</span> : prise en charge à <span class=\"kw-chiffre\">100 %</span> des soins liés à l'affection.</li>\n        <li>L'IRC grave est aussi le <strong>critère HAS</strong> de prescription de l'<span class=\"kw-ttt\">oxygénothérapie de longue durée</span>.</li>\n      </ul>\n      <p class=\"obj-source\"><em>Volet médico-social limité à l'<span class=\"kw-def\">ALD</span> 14 dans la trame de l'item 208 (fiche source et Collège de pneumologie concordants).</em></p>","frequence":0},{"id":"208-13","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de l’oxygénothérapie et de sa surveillance chez un malade hypercapnique","contenu":"<p>Chez le malade <span class=\"kw-def\">hypercapnique</span>, l'<span class=\"kw-ttt\">oxygénothérapie</span> reste indiquée mais doit être <strong>titrée et surveillée</strong> : un apport d'O₂ excessif et non contrôlé peut <span class=\"kw-alerte\">aggraver l'hypercapnie</span> et précipiter une <span class=\"kw-alerte\">acidose respiratoire</span>.</p>\n      <div class=\"callout callout-warn\"><strong>Principe clé.</strong> l'<span class=\"kw-def\">hypercapnie</span> n'est pas une <span class=\"kw-ci\">contre-indication</span> à l'oxygène, <strong>à condition d'être corrigée par une <span class=\"kw-ttt\">ventilation à domicile</span></strong> (<span class=\"kw-ttt\">VNI</span>). On vise une oxygénation suffisante (<span class=\"kw-bio\">SpO₂</span> cible) sans sur-oxygéner, avec contrôle <span class=\"kw-bio\">gazométrique</span>.</div>\n      <p><strong>Ventilation à domicile</strong> — principe : délivrer une <span class=\"kw-def\">pression positive</span> pour assister <span class=\"kw-clinique\">les</span> muscles inspiratoires, augmenter la ventilation-minute et corriger l'<span class=\"kw-def\">hypoventilation alvéolaire</span> (nocturne ++ et diurne).</p>\n      <table >\n        <thead><tr><th>Indication</th><th>Modalités &amp; bénéfices</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-def\">IRC restrictive</span></th><td>Indiquée <strong>dès <span class=\"kw-clinique\">les</span> 1ers signes</strong> d'hypoventilation alvéolaire diurne et/ou nocturne ; améliore la <span class=\"kw-clinique\">survie</span> et la qualité de vie</td></tr>\n          <tr><th><span class=\"kw-def\">IRC obstructive</span></th><td>Indiquée en cas d'<span class=\"kw-bio\">hypercapnie diurne importante</span> ; améliore survie, qualité de vie, <span class=\"kw-clinique\">dyspnée</span> et fréquence des hospitalisations</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Modalités :</strong> <span class=\"kw-ttt\">ventilation non invasive</span> par masque nasal ou naso-buccal, à domicile, la <strong>nuit</strong> (voire prolongée la journée dans <span class=\"kw-clinique\">les</span> maladies neuromusculaires). <strong>Efficacité :</strong> amélioration de la <span class=\"kw-bio\">PaCO₂</span>, de la <span class=\"kw-clinique\">dyspnée</span> et du <span class=\"kw-clinique\">sommeil</span>.</p>","frequence":2},{"id":"208-14","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications des examens d’imagerie devant une insuffisance respiratoire chronique","contenu":"<p>L'imagerie de l'IRC vise l'<strong>orientation étiologique</strong> et l'évaluation du <strong>retentissement</strong> cardiaque.</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Indication</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-imagerie\">RXT ± TDM thoracique</span></th><td>Orientation <span class=\"kw-etio\">étiologique</span> (parenchyme, plèvre, distension, fibrose)</td></tr>\n          <tr><th><span class=\"kw-imagerie\">Échographie cardiaque (ETT)</span></th><td>Retentissement sur le <span class=\"kw-clinique\">ventricule droit</span> (systématique) : mesure de la <span class=\"kw-imagerie\">PAP systolique</span> ; <span class=\"kw-def\">dépistage</span> d'une <span class=\"kw-clinique\">insuffisance cardiaque</span> et des <span class=\"kw-def\">comorbidités</span> cardiovasculaires (pertinent surtout dans la <span class=\"kw-etio\">BPCO</span>)</td></tr>\n          <tr><th><span class=\"kw-bio\">Cathétérisme cardiaque droit</span></th><td>Confirmation d'une <span class=\"kw-alerte\">HTAP</span> (à l'état stable = signification péjorative) — rarement indiqué si IRC déjà documentée</td></tr>\n          <tr><th><span class=\"kw-bio\">ECG</span></th><td>Signes d'<span class=\"kw-clinique\">hypertrophie des cavités droites</span></td></tr>\n          <tr><th><span class=\"kw-bio\">NFS</span></th><td><span class=\"kw-clinique\">Polyglobulie</span> (témoin d'hypoxémie chronique, rare aujourd'hui)</td></tr>\n          <tr><th>Tests d'exercice</th><td><span class=\"kw-bio\">Test de marche de 6 min</span>, test de lever de chaise, EFR à l'exercice : valeur <strong>pronostique</strong> et orientation thérapeutique</td></tr>\n        </tbody>\n      </table>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré :</strong> <span class=\"kw-alerte\">décompensation</span> en <span class=\"kw-alerte\">insuffisance respiratoire aiguë</span> (<span class=\"kw-etio\">IRA</span>) = principal risque évolutif de l'IRC<br><strong>1er geste :</strong> <span class=\"kw-ttt\">oxygénothérapie</span> (traitement clé) ± <span class=\"kw-ttt\">ventilation mécanique</span> si acidose respiratoire décompensée (IRA hypercapnique)<br><strong>Déclencheurs :</strong> <span class=\"kw-etio\">infections respiratoires basses</span> ; <span class=\"kw-etio\">OAP</span> ; <span class=\"kw-etio\">troubles du rythme</span> ; <span class=\"kw-etio\">EP</span> ; <span class=\"kw-ttt\">benzodiazépines</span>/<span class=\"kw-ttt\">opiacés</span> ; aucune cause dans <span class=\"kw-chiffre\">⅓</span> des cas</p>","redflags":"<ul><li>Signes de <span class=\"kw-alerte\">lutte</span> et signes de <span class=\"kw-alerte\">défaillance</span> respiratoire</li><li><span class=\"kw-bio\">pH</span> <span class=\"kw-chiffre\">&lt; 7,35</span> (acidose respiratoire décompensée)</li><li><span class=\"kw-bio\">PaO2</span> <span class=\"kw-chiffre\">&lt; 60 mmHg</span> (définit l'<span class=\"kw-def\">IRC grave</span>)</li><li><span class=\"kw-bio\">PaCO2</span> <span class=\"kw-chiffre\">&gt; 45 mmHg</span> (hypercapnie)</li><li>Élévation des <span class=\"kw-bio\">lactates</span></li><li>Troubles de la conscience jusqu'au <span class=\"kw-alerte\">coma hypercapnique</span></li><li><span class=\"kw-clinique\">Cyanose</span> (&gt; <span class=\"kw-chiffre\">5 g/dL</span> d'<span class=\"kw-bio\">hémoglobine</span> désoxygénée)</li><li>Signes d'<span class=\"kw-clinique\">insuffisance cardiaque droite</span> à un <span class=\"kw-def\">stade</span> évolué (TJ, RHJ, OMI)</li><li><span class=\"kw-clinique\">Astérixis</span> / <span class=\"kw-clinique\">flapping</span> tremor (hypercapnie)</li></ul>","principes":"<p>Traiter la cause, corriger l'hypoxémie et prévenir <span class=\"kw-clinique\">les</span> complications.</p><p><strong>Traitement de la cause</strong></p><ul><li>Traitement de la <span class=\"kw-ttt\">maladie causale</span> (étiologie)</li></ul><p><strong>Mode de vie</strong></p><ul><li><span class=\"kw-ttt\">Sevrage tabagique</span> impératif quelle que soit la cause</li><li><span class=\"kw-ttt\">Activité physique</span> : dans la BPCO, survie améliorée pour <span class=\"kw-chiffre\">30 min/jour</span> ou <span class=\"kw-chiffre\">≥ 2h/semaine</span></li></ul><p><strong><span class=\"kw-ttt\">Vaccination</span></strong></p><ul><li><span class=\"kw-ttt\">Anti-grippale</span> annuelle : quasi-totalité des IRC (sauf CI)</li><li><span class=\"kw-ttt\">Anti-pneumococcique</span> : <span class=\"kw-etio\">BPCO</span> et <span class=\"kw-etio\">maladies neuromusculaires</span></li></ul><p><strong>Appareillages à domicile</strong></p><ul><li><span class=\"kw-ttt\">Oxygénothérapie de longue durée</span> (OLD)</li><li><span class=\"kw-ttt\">Ventilation à domicile</span> (<span class=\"kw-ttt\">VNI</span>) pour corriger l'hypoventilation alvéolaire (nocturne ++ et diurne)</li></ul><p><strong>Réhabilitation respiratoire</strong></p><ul><li>Indiquée quel que soit le <span class=\"kw-def\">stade</span> dès qu'il existe un handicap persistant (<span class=\"kw-clinique\">dyspnée</span> seule incluse) malgré le traitement de la cause ou un appareillage</li><li>2 composantes : <span class=\"kw-ttt\">réentraînement à l'exercice</span> + <span class=\"kw-ttt\">éducation thérapeutique</span></li></ul><p><strong>Kinésithérapie respiratoire</strong></p><ul><li>Recrutement alvéolaire : <span class=\"kw-etio\">maladies neuromusculaires</span> avancées, syndromes restrictifs sévères</li><li>Aide à la <span class=\"kw-clinique\">toux</span> : toux inefficace</li><li>Désencombrement : encombrement bronchique aigu</li><li><span class=\"kw-ttt\">Drainage</span> au long cours : <span class=\"kw-etio\">dilatation des bronches</span></li></ul><p><strong>Transplantation</strong></p><ul><li><span class=\"kw-ttt\">Transplantation pulmonaire</span> : très faible nombre de patients rigoureusement sélectionnés</li></ul>","suivi":"<p>Surveiller l'efficacité de l'<span class=\"kw-ttt\">oxygénothérapie</span> et dépister <span class=\"kw-clinique\">les</span> complications de l'IRC.</p><p><strong><span class=\"kw-ttt\">Oxygénothérapie</span> de longue durée</strong></p><p>CI : <span class=\"kw-ci\">tabagisme actif</span> (risque de brûlures graves du visage, voire incendie)</p><ul><li>Objectif : <span class=\"kw-bio\">PaO2</span> <span class=\"kw-chiffre\">&gt; 60 mmHg</span> ou <span class=\"kw-bio\">SpO2/SaO2</span> <span class=\"kw-chiffre\">&gt; 90%</span> au repos et à l'effort</li><li>Durée : idéalement <span class=\"kw-chiffre\">24h/24</span>, au minimum <span class=\"kw-chiffre\">≥ 15h/jour</span> (couvrant la nuit et l'activité physique)</li></ul><p><strong>Oxygène chez l'hypercapnique</strong></p><ul><li>L'<span class=\"kw-etio\">hypercapnie</span> n'est PAS une <span class=\"kw-ci\">contre-indication</span> à l'oxygène</li><li>À condition d'être corrigée par une <span class=\"kw-ttt\">ventilation à domicile</span></li></ul><p><strong>Complications à dépister</strong></p><ul><li><span class=\"kw-bio\">Polyglobulie</span> (hyperviscosité → risque de thromboses artérielles/veineuses)</li><li><span class=\"kw-etio\">HTP</span> / cœur pulmonaire chronique et <span class=\"kw-clinique\">insuffisance ventriculaire droite</span></li><li><span class=\"kw-clinique\">Rétention hydrosodée</span> (<span class=\"kw-clinique\">œdèmes</span> déclives)</li></ul><p><strong><span class=\"kw-imagerie\">Échographie</span> cardiaque (<span class=\"kw-imagerie\">ETT</span>)</strong></p><ul><li>Retentissement sur le <span class=\"kw-clinique\">ventricule droit</span> (mesure de la <span class=\"kw-clinique\">PAP systolique</span>), systématique</li><li><span class=\"kw-etio\">HTP</span> suspectée si <span class=\"kw-chiffre\">PAPS &gt; 35 mmHg</span>, confirmée par cathétérisme cardiaque droit (<span class=\"kw-chiffre\">PAPm &gt; 20 mmHg</span> + résistances <span class=\"kw-chiffre\">&gt; 3 UW</span>) ; valeur péjorative</li><li><span class=\"kw-def\">Dépistage</span> d'<span class=\"kw-ci\">insuffisance cardiaque</span> et de <span class=\"kw-def\">comorbidités</span> cardiovasculaires (surtout BPCO)</li></ul><p><strong>Médico-social</strong></p><ul><li><span class=\"kw-def\">IRC grave</span> (<span class=\"kw-bio\">PaO2</span> <span class=\"kw-chiffre\">&lt; 60 mmHg</span>) : <span class=\"kw-ttt\">ALD 14</span> avec exonération du ticket modérateur</li></ul>"},"liensGlobaux":[{"href":"https://cep-1f48c.kxcdn.com/wp-content/uploads/2023/07/ITEM_208_INSUFFISANCE_RESPIRATOIRE_CHRONIQUE_2023.pdf","label":"Collège pneumo — référentiel 208 (2023)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"IRC confirmée — PaO2 &lt; 70 mmHg à l'état stable","detail":"<h4>CAT — Indication de l'<span class=\"kw-ttt\">oxygénothérapie</span> de longue durée (OLD) — <span class=\"kw-bio\">GDS</span> au repos, en <span class=\"kw-def\">air</span> ambiant, à l'état stable, à 2 reprises <span class=\"kw-chiffre\">≥ 2 semaines</span> d'intervalle</h4>","branches":[{"to":"q-type","label":"GDS confirment l'IRC","color":"blue"}]},{"id":"q-type","kind":"decision","label":"Type d'IRC selon les EFR ? — Trouble ventilatoire obstructif (TVO) ou restrictif (TVR)","branches":[{"to":"q-restr","label":"IRC restrictive (TVR)","color":"blue"},{"to":"q-obstr","label":"IRC obstructive (TVO)","color":"blue"}]},{"id":"q-restr","kind":"decision","label":"PaO2 &lt; 60 mmHg ?","branches":[{"to":"t-old-restr","label":"PaO2 &lt; 60 mmHg","color":"blue"},{"to":"t-noold-restr","label":"PaO2 ≥ 60 mmHg","color":"green"}]},{"id":"t-old-restr","kind":"terminal","label":"OLD remboursée — mise en place","color":"blue","detail":"<h4>Confirmation</h4><ul><li>IRC restrictive : OLD remboursée si <span class=\"kw-bio\">PaO2</span> <span class=\"kw-chiffre\">&lt; 60 mmHg</span></li></ul><h4>Conduite</h4><ul><li>À domicile, par <span class=\"kw-ttt\">lunettes nasales</span></li><li>Idéalement <span class=\"kw-chiffre\">24h/24</span>, au minimum <span class=\"kw-chiffre\">≥ 15h/jour</span> (nuit + activité physique)</li><li>Débit pour obtenir <span class=\"kw-bio\">PaO2</span> <span class=\"kw-chiffre\">&gt; 60 mmHg</span> ou <span class=\"kw-bio\">SpO2/SaO2</span> <span class=\"kw-chiffre\">&gt; 90%</span></li></ul><h4>À retenir</h4><ul><li><span class=\"kw-ci\">Tabagisme actif</span> remet en cause le traitement (brûlures, incendie)</li><li>L'<span class=\"kw-etio\">hypercapnie</span> n'est pas une CI si corrigée par ventilation à domicile</li></ul>"},{"id":"t-noold-restr","kind":"terminal","label":"Pas d'indication à l'OLD","color":"green","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-bio\">PaO2</span> <span class=\"kw-chiffre\">≥ 60 mmHg</span> : pas de <span class=\"kw-def\">critère de</span> remboursement</li><li><span class=\"kw-def\">Surveillance</span> des <span class=\"kw-bio\">gaz du sang</span>, traitement de la cause, <span class=\"kw-ttt\">sevrage tabagique</span></li></ul>"},{"id":"q-obstr","kind":"decision","label":"Niveau de PaO2 ?","branches":[{"to":"t-old-obstr","label":"PaO2 &lt; 55 mmHg","color":"blue"},{"to":"t-old-cond","label":"PaO2 55–60 mmHg","color":"amber"},{"to":"t-noold-obstr","label":"PaO2 &gt; 60 mmHg","color":"green"}]},{"id":"t-old-obstr","kind":"terminal","label":"OLD remboursée — mise en place","color":"blue","detail":"<h4>Confirmation</h4><ul><li>IRC obstructive : OLD remboursée si <span class=\"kw-bio\">PaO2</span> <span class=\"kw-chiffre\">&lt; 55 mmHg</span></li></ul><h4>Conduite</h4><ul><li>À domicile, lunettes nasales, idéalement <span class=\"kw-chiffre\">24h/24</span> (minimum <span class=\"kw-chiffre\">≥ 15h/jour</span>)</li><li>Objectif <span class=\"kw-bio\">PaO2</span> <span class=\"kw-chiffre\">&gt; 60 mmHg</span> ou <span class=\"kw-bio\">SpO2</span> <span class=\"kw-chiffre\">&gt; 90%</span> au repos et à l'effort</li></ul>"},{"id":"t-old-cond","kind":"terminal","label":"OLD si signe d'hypoxie tissulaire","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-bio\">PaO2</span> entre <span class=\"kw-chiffre\">55–60 mmHg</span> : OLD remboursée UNIQUEMENT en présence d'<span class=\"kw-chiffre\">≥ 1</span> signe d'hypoxie tissulaire</li><li>Sinon : pas d'indication, <span class=\"kw-def\">surveillance</span> des <span class=\"kw-bio\">gaz du sang</span></li></ul><h4>Signes d'hypoxie tissulaire (<span class=\"kw-chiffre\">≥ 1</span>)</h4><ul><li><span class=\"kw-bio\">Polyglobulie</span> : <span class=\"kw-bio\">hématocrite</span> <span class=\"kw-chiffre\">&gt; 55%</span></li><li><span class=\"kw-clinique\">Insuffisance ventriculaire droite</span> et <span class=\"kw-etio\">HTAP</span> (clinique, <span class=\"kw-imagerie\">ETT</span> ou cathétérisme)</li><li>Désaturations artérielles nocturnes non apnéiques : <span class=\"kw-bio\">SpO2 nocturne moyenne ≤ 88%</span></li><li><span class=\"kw-clinique\">OMI</span> chronique</li></ul>"},{"id":"t-noold-obstr","kind":"terminal","label":"Pas d'indication à l'OLD","color":"green","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-bio\">PaO2</span> <span class=\"kw-chiffre\">&gt; 60 mmHg</span> : pas de <span class=\"kw-def\">critère de</span> remboursement</li><li><span class=\"kw-def\">Surveillance</span> des <span class=\"kw-bio\">gaz du sang</span>, traitement de la cause, <span class=\"kw-ttt\">sevrage tabagique</span></li></ul>"}]},"cards":[{"i":"8a35f1ad118d","n":208,"o":"208-1","u":"Diagnostic positif","t":"Connaître la définition d’une insuffisance respiratoire chronique (IRC)","q":"Quelles sont les trois étiologies les plus fréquentes de l'insuffisance respiratoire chronique ?","a":"<ul><li>La <strong>BPCO</strong> (bronchopneumopathie chronique obstructive)</li><li>Le <strong>syndrome obésité-hypoventilation</strong></li><li>Les <strong>maladies neuromusculaires</strong></li></ul>"},{"i":"8eb31dcf8210","n":208,"o":"208-1","u":"Diagnostic positif","t":"Connaître la définition d’une insuffisance respiratoire chronique (IRC)","q":"Quelle est la définition gazométrique stricte de l'insuffisance respiratoire chronique (IRC) ?","a":"<p>L'IRC est définie gazométriquement par une <strong>hypoxémie</strong>, c'est-à-dire une Pression artérielle en O₂ (PaO₂) <strong>inférieure à 70 mmHg</strong>, mesurée en <strong>air ambiant</strong>, au <strong>repos</strong>, à l'<strong>état stable</strong>, et confirmée à <strong>2 reprises</strong> à au moins <strong>2 semaines d'intervalle</strong>.</p>"},{"i":"a58f5d555817","n":208,"o":"208-1","u":"Diagnostic positif","t":"Connaître la définition d’une insuffisance respiratoire chronique (IRC)","q":"Comment est définie l'IRC grave et quelles sont ses implications en termes de prise en charge et de droits ?","a":"<p>L'IRC grave est définie par une <strong>PaO₂ &lt; 60 mmHg</strong>. Elle constitue un critère de prescription d'<strong>oxygénothérapie de longue durée</strong> (OLD) reconnue par la HAS et ouvre droit à l'exonération du ticket modérateur au titre de l'<strong>ALD 14</strong>.</p>"},{"i":"ad812d123a7d","n":208,"o":"208-1","u":"Diagnostic positif","t":"Connaître la définition d’une insuffisance respiratoire chronique (IRC)","q":"Comment définir cliniquement l'insuffisance respiratoire chronique (IRC) ?","a":"<p>L'insuffisance respiratoire chronique est l'<strong>incapacité de l'appareil respiratoire à assurer les échanges gazeux</strong> (oxygénation du sang et élimination du CO₂). C'est un processus <strong>irréversible</strong>, lentement évolutif dans la majorité des cas.</p>"},{"i":"eb7d82623793","n":208,"o":"208-1","u":"Diagnostic positif","t":"Connaître la définition d’une insuffisance respiratoire chronique (IRC)","q":"Quelles sont les deux formes gazométriques principales de l'insuffisance respiratoire chronique (IRC) ?","a":"<ul><li>L'<strong>IRC hypoxémique</strong> : PaO₂ diminuée avec une PaCO₂ normale ou diminuée.</li><li>L'<strong>IRC hypercapnique</strong> : PaO₂ diminuée avec une PaCO₂ augmentée.</li></ul>"},{"i":"28a7f3b82d9d","n":208,"o":"208-2","u":"Diagnostic positif","t":"Connaître les données cliniques permettant d’orienter vers une IRC obstructive et vers une IRC restrictive","q":"Quels sont les principaux signes et symptômes évocateurs d'une insuffisance respiratoire chronique restrictive type fibrose pulmonaire ou maladie neuromusculaire ?","a":"<ul><li><strong>Dyspnée d'effort</strong></li><li><strong>Toux sèche</strong> (en cas de fibrose pulmonaire).</li><li><strong>Encombrements bronchiques itératifs</strong> (en cas de maladie neuromusculaire).</li><li>Signes d'altération du sommeil, notamment la <strong>somnolence diurne excessive</strong> ou les <strong>céphalées matinales</strong>.</li></ul>"},{"i":"3103a381baf0","n":208,"o":"208-2","u":"Diagnostic positif","t":"Connaître les données cliniques permettant d’orienter vers une IRC obstructive et vers une IRC restrictive","q":"Quels sont les principaux signes et symptômes évocateurs d'une insuffisance respiratoire chronique obstructive ?","a":"<ul><li><strong>Dyspnée d'effort</strong></li><li><strong>Toux</strong> (avec ou sans expectorations), suggérant notamment une BPCO.</li><li>Signes d'altération du sommeil tels que <strong>somnolence diurne excessive</strong>, <strong>céphalées matinales</strong>, et <strong>troubles de la concentration</strong> peuvent également orienter.</li></ul>"},{"i":"a3459d12cdad","n":208,"o":"208-2","u":"Diagnostic positif","t":"Connaître les données cliniques permettant d’orienter vers une IRC obstructive et vers une IRC restrictive","q":"Quelle est le symptôme quasi-constant de l'insuffisance respiratoire chronique (IRC) ?","a":"<p>La <strong>dyspnée</strong> est le symptôme quasi-constant de l'IRC. Elle évolue d'une dyspnée d'effort à une dyspnée pour des efforts modestes, voire au repos.</p>"},{"i":"a38c6809a113","n":208,"o":"208-2","u":"Diagnostic positif","t":"Connaître les données cliniques permettant d’orienter vers une IRC obstructive et vers une IRC restrictive","q":"Quels sont les signes cliniques généraux pouvant orienter vers le diagnostic d'insuffisance respiratoire chronique, indépendamment du mécanisme obstructive ou restrictif ?","a":"<ul><li><strong>Cyanose</strong> (signe de gravité inconstant, traduisant la présence de &gt; 5 g/dL d'hémoglobine désoxygénée).</li><li>Signes d'<strong>insuffisance cardiaque droite</strong> à un stade évolué : <strong>turgescence jugulaire</strong>, <strong>reflux hépato-jugulaire</strong>, <strong>œdèmes des membres inférieurs</strong>.</li><li>Signes d'<strong>hypercapnie</strong> : <strong>astérixis</strong>, <strong>céphalées</strong>, <strong>hypervascularisation des conjonctives</strong>, <strong>sueurs</strong>, <strong>tachycardie</strong>, <strong>HTA</strong>, troubles de la vigilance jusqu'au coma.</li><li>Altération de la qualité du sommeil : <strong>sommeil non réparateur</strong>, <strong>réveils nocturnes</strong>, <strong>céphalées frontales matinales</strong>, <strong>somnolence diurne excessive</strong>, <strong>troubles de la mémoire et de la concentration</strong>, <strong>syndrome anxio-dépressif</strong>.</li></ul>"},{"i":"1344c5647624","n":208,"o":"208-3","u":"Définition","t":"Connaître la définition de l’hypertension pulmonaire (HTP) de l’adulte","q":"Comment définit-on l'hypertension pulmonaire (HTP) de l'adulte selon les critères hémodynamiques invasifs ?","a":"<p>L'hypertension pulmonaire (HTP) de l'adulte est définie par deux critères mesurés par cathétérisme cardiaque droit :</p><ul><li>Une <strong>Pression Artérielle Pulmonaire moyenne (PAPm) > 20 mmHg</strong>.</li><li>Des <strong>Résistances Vasculaires Pulmonaires (RVP) > 3 unités Wood</strong>.</li></ul>"},{"i":"441e72a1f742","n":208,"o":"208-3","u":"Définition","t":"Connaître la définition de l’hypertension pulmonaire (HTP) de l’adulte","q":"Quel est le mécanisme principal de l'hypertension pulmonaire (HTP) secondaire à une insuffisance respiratoire chronique ?","a":"<p>L'HTP secondaire à une insuffisance respiratoire chronique (IRC) est principalement due à la <strong>vasoconstriction pulmonaire hypoxique</strong>, qui entraîne à long terme un <strong>remodelage vasculaire</strong>.</p>"},{"i":"8baa2ae6a8fb","n":208,"o":"208-3","u":"Définition","t":"Connaître la définition de l’hypertension pulmonaire (HTP) de l’adulte","q":"Dans quelle classification se situe l'hypertension pulmonaire (HTP) secondaire à une insuffisance respiratoire chronique (IRC) ?","a":"<p>Lorsqu'elle est secondaire à une insuffisance respiratoire chronique (IRC), l'HTP est classée dans le <strong>groupe 3</strong> de la classification.</p>"},{"i":"1ea631534671","n":208,"o":"208-5","u":"Examens complémentaires","t":"Connaître les explorations fonctionnelles permettant d’orienter vers une IRC obstructive et vers une IRC restrictive","q":"Quelle est l'orientation diagnostique d'une insuffisance respiratoire chronique obstructive (TVO) mise en évidence par les explorations fonctionnelles respiratoires ?","a":"<p>Une IRC obstructive est principalement orientée vers des pathologies comme la <strong>BPCO</strong> (cause principale), à rechercher systématiquement. Elle peut aussi être liée à un <strong>asthme fixé vieilli</strong> ou à une <strong>bronchiolite</strong>.</p>"},{"i":"7933635b6fba","n":208,"o":"208-5","u":"Examens complémentaires","t":"Connaître les explorations fonctionnelles permettant d’orienter vers une IRC obstructive et vers une IRC restrictive","q":"Quelles étiologies orientent vers une insuffisance respiratoire chronique restrictive (TVR) avec anomalie de diffusion aux EFR ?","a":"<p>Une IRC restrictive avec anomalie de diffusion oriente principalement vers les <strong>pneumopathies interstitielles</strong>, notamment la <strong>fibrose pulmonaire</strong>, signant une atteinte de la diffusion alvéolo-capillaire.</p>"},{"i":"839766266407","n":208,"o":"208-5","u":"Examens complémentaires","t":"Connaître les explorations fonctionnelles permettant d’orienter vers une IRC obstructive et vers une IRC restrictive","q":"Quelles sont les causes d'une insuffisance respiratoire chronique restrictive (TVR) sans anomalie de diffusion aux EFR ?","a":"<p>Une IRC restrictive sans anomalie de diffusion évoque :<ul><li>Les <strong>maladies neuromusculaires</strong>.</li><li>Le <strong>syndrome obésité-hypoventilation</strong>.</li><li>Une atteinte de la <strong>paroi thoracique</strong> (ex: cyphoscoliose).</li><li>Les atteintes pleurales comme la <strong>pachypleurite</strong>.</li></ul></p>"},{"i":"f9484d35f1f5","n":208,"o":"208-5","u":"Examens complémentaires","t":"Connaître les explorations fonctionnelles permettant d’orienter vers une IRC obstructive et vers une IRC restrictive","q":"Quel mécanisme physiologique est caractéristique de l'insuffisance respiratoire chronique obstructive (TVO) ?","a":"<p>Le mécanisme caractéristique d'une IRC obstructive est une <strong>inadéquation ventilation/perfusion</strong>, souvent efficacement corrigée par l'<strong>oxygénothérapie de longue durée</strong>.</p>"},{"i":"1ecbeebe6ea8","n":208,"o":"208-7","u":"Identifier une urgence","t":"Identifier une décompensation d’IRC et en apprécier la gravité","q":"Quels sont les signes de gravité biologiques d'une décompensation d'Insuffisance Respiratoire Chronique (IRC) ?","a":"<ul><li>Un <strong>pH &lt; 7,35</strong>.</li><li>Une <strong>PaO₂ &lt; 60 mmHg</strong>.</li><li>Une <strong>PaCO₂ &gt; 45 mmHg</strong>.</li><li>Une <strong>élévation des lactates</strong>.</li></ul>"},{"i":"2a496ebbe55e","n":208,"o":"208-7","u":"Identifier une urgence","t":"Identifier une décompensation d’IRC et en apprécier la gravité","q":"Quels autres facteurs peuvent déclencher une décompensation d'Insuffisance Respiratoire Chronique (IRC) ?","a":"<ul><li>La prise de <strong>médicaments sédatifs</strong> comme les benzodiazépines ou les opiacés.</li><li>La <strong>chirurgie abdominale sus-mésocolique ou thoracique</strong>.</li><li>Un <strong>traumatisme thoracique</strong>.</li><li>Une <strong>fracture-tassement vertébral</strong>.</li><li>Un <strong>pneumothorax</strong>.</li><li>Il est important de noter qu'aucune cause n'est retrouvée dans <strong>un tiers des cas</strong>.</li></ul>"},{"i":"412ee87158dc","n":208,"o":"208-7","u":"Identifier une urgence","t":"Identifier une décompensation d’IRC et en apprécier la gravité","q":"Quelles sont les causes les plus fréquentes d'exacerbation ou de décompensation de l'Insuffisance Respiratoire Chronique (IRC) ?","a":"<ul><li>Les <strong>infections respiratoires basses</strong> (bronchites, pneumonies).</li><li>L'<strong>œdème aigu du poumon</strong> (OAP).</li><li>Les <strong>troubles du rythme</strong>.</li><li>L'<strong>embolie pulmonaire</strong>.</li></ul>"},{"i":"b6b04259fafe","n":208,"o":"208-7","u":"Identifier une urgence","t":"Identifier une décompensation d’IRC et en apprécier la gravité","q":"Quelle est la principale complication d'une Insuffisance Respiratoire Chronique (IRC) ?","a":"<p>La principale complication de l'IRC est la <strong>décompensation en insuffisance respiratoire aiguë</strong> (IRA).</p>"},{"i":"c9bad5a0f5fa","n":208,"o":"208-7","u":"Identifier une urgence","t":"Identifier une décompensation d’IRC et en apprécier la gravité","q":"Comment doit être prise en charge la décompensation d'une Insuffisance Respiratoire Chronique (IRC) hypercapnique ?","a":"<p>La prise en charge repose sur l'<strong>oxygénothérapie</strong>, qui est le traitement clé. Une <strong>ventilation mécanique</strong> peut être nécessaire en cas d'acidose respiratoire décompensée.</p>"},{"i":"083ab4442dd6","n":208,"o":"208-8","u":"Suivi et/ou pronostic","t":"Connaître les conséquences de l’IRC : insuffisance respiratoire aigüe, polyglobulie, hypertension pulmonaire, rétention hydrosodée","q":"Quelles sont les causes et la présentation clinique de la rétention hydrosodée en cas d'insuffisance respiratoire chronique ?","a":"<p>La rétention hydrosodée peut être due à une <strong>anomalie de régulation du facteur natriurétique</strong> ou être une conséquence de l'<strong>hypertension artérielle pulmonaire (HTAP)</strong> secondaire. Cliniquement, elle se manifeste par des <strong>œdèmes déclives</strong> fréquents.</p>"},{"i":"3181c442ac4c","n":208,"o":"208-8","u":"Suivi et/ou pronostic","t":"Connaître les conséquences de l’IRC : insuffisance respiratoire aigüe, polyglobulie, hypertension pulmonaire, rétention hydrosodée","q":"Quel est le mécanisme et la signification pronostique de l'hypertension pulmonaire dans l'insuffisance respiratoire chronique ?","a":"<p>L'hypertension pulmonaire est secondaire à la <strong>vasoconstriction pulmonaire hypoxique</strong>, qui entraîne un <strong>remodelage vasculaire</strong>. Cela mène à un <strong>cœur pulmonaire chronique</strong>, aggravé par l'augmentation des résistances vasculaires pulmonaires, l'hyperviscosité sanguine et la rétention hydrosodée, aboutissant à une <strong>dysfonction ventriculaire droite</strong>. Sa présence a une <strong>signification péjorative</strong> sur le pronostic.</p>"},{"i":"a717539e6ebf","n":208,"o":"208-8","u":"Suivi et/ou pronostic","t":"Connaître les conséquences de l’IRC : insuffisance respiratoire aigüe, polyglobulie, hypertension pulmonaire, rétention hydrosodée","q":"Quels sont les principaux signes cliniques d'hypercapnie à reconnaître lors d'une décompensation d'insuffisance respiratoire chronique ?","a":"<p>Les signes d'hypercapnie incluent :</p><ul><li>Sur la <strong>vigilance</strong> : <strong>agitation</strong>, <strong>confusion</strong>, <strong>ralentissement idéo-moteur</strong>, pouvant aller jusqu'au <strong>coma hypercapnique</strong>.</li><li>Une <strong>réponse adrénergique</strong> : <strong>tremblements</strong>, <strong>sueurs</strong>, <strong>tachycardie</strong>, <strong>HTA</strong>.</li><li>Un <strong>effet vasodilatateur du CO₂</strong> : <strong>céphalées</strong>, <strong>hypervascularisation conjonctivale</strong>.</li><li>Le <strong>signe clé</strong> est l'<strong>astérixis</strong> (ou <strong>flapping tremor</strong>).</li></ul>"},{"i":"cc93ce6fa94a","n":208,"o":"208-8","u":"Suivi et/ou pronostic","t":"Connaître les conséquences de l’IRC : insuffisance respiratoire aigüe, polyglobulie, hypertension pulmonaire, rétention hydrosodée","q":"Quel est le mécanisme de la polyglobulie observée lors de l'insuffisance respiratoire chronique et quelles en sont les conséquences ?","a":"<p>La polyglobulie résulte d'une production d'<strong>érythropoïétine (EPO)</strong> en réponse à l'<strong>hypoxémie chronique</strong>. Ce phénomène adaptatif, bien qu'inconstant, entraîne une <strong>augmentation de la viscosité sanguine</strong>, augmentant le risque de <strong>thromboses artérielles et veineuses</strong>.</p>"}]};